#c57 .stage{min-height:520px}
/* country select */
.cc{position:relative;width:100%;max-width:320px;align-self:flex-start;margin-top:12px;display:flex;flex-direction:column;gap:6px}
.cc-lab{font-size:12.5px;font-weight:500;color:var(--text-dim)}
.cc-trig{display:flex;align-items:center;gap:10px;height:44px;padding:0 12px;background:var(--panel);border:1px solid var(--icon-line);text-align:left;transition:border-color .2s,box-shadow .2s}
.cc-trig[aria-expanded="true"],.cc-trig:focus-visible{border-color:var(--accent);box-shadow:0 0 0 3px var(--accent-bg);outline:none}
.cc-flag{width:22px;height:22px;flex:none;border-radius:50%;box-shadow:0 0 0 1px rgba(0,0,0,.06)}
.cc-name{flex:1;font-size:14px;font-weight:500}
.cc-car{color:var(--muted);transition:transform .35s var(--ease)}
.cc-trig[aria-expanded="true"] .cc-car{transform:rotate(180deg)}
.cc-pop{position:absolute;left:0;right:0;top:calc(100% + 6px);z-index:4;background:var(--panel);border:1px solid var(--icon-line);padding:6px;opacity:0;visibility:hidden;transform:translateY(-4px) scale(.99);transform-origin:top center;transition:opacity .2s ease,transform .3s var(--ease),visibility 0s linear .3s;box-shadow:0 16px 36px -18px rgba(0,0,0,.35)}
.cc-pop.show{opacity:1;visibility:visible;transform:none;transition:opacity .2s ease,transform .3s var(--ease),visibility 0s}
.cc-search{display:flex;align-items:center;gap:8px;padding:8px 10px;background:var(--chip);margin-bottom:4px;color:var(--muted)}
.cc-search input{flex:1;min-width:0;background:transparent;border:0;outline:0;color:var(--text);font:inherit;font-size:13.5px}
.cc-list{max-height:236px;overflow-y:auto;scrollbar-width:thin;scrollbar-color:var(--line) transparent}
.cc-it{display:flex;align-items:center;gap:10px;width:100%;padding:8px 10px;text-align:left;font-size:13.5px;color:var(--text);border:1px solid transparent;transition:background-color .15s,border-color .15s}
.cc-it .code{margin-left:auto;font-size:12px;color:var(--muted);font-family:var(--mono)}
.cc-it .ms{font-size:14px;color:var(--accent);opacity:0}
.cc-it.sel .ms{opacity:1}
.cc-it.act{background:var(--chip);border-color:var(--line)}
.cc-none{padding:16px;text-align:center;font-size:13px;color:var(--muted)}

/* ---------- country select ---------- */
{
  const trig = $('#cc-trig'), pop = $('#cc-pop'), q = $('#cc-q'), list = $('#cc-list');
  const countries = [['au','Australia'],['br','Brazil'],['ca','Canada'],['fr','France'],['de','Germany'],['it','Italy'],['jp','Japan'],['nl','Netherlands'],['pl','Poland'],['pt','Portugal'],['es','Spain'],['se','Sweden'],['gb','United Kingdom'],['us','United States']];
  let sel = 'pl', shown = [], idx = 0;
  function paintTrig(){ const c = countries.find(x => x[0] === sel); $('#cc-flag').src = FLAGS[sel]; $('#cc-name').textContent = c[1]; }
  function render(){
    const v = q.value.trim().toLowerCase();
    shown = countries.filter(c => c[1].toLowerCase().includes(v) || c[0].includes(v));
    list.innerHTML = shown.length ? shown.map((c, i) => `<button class="cc-it ${c[0] === sel ? 'sel' : ''}" role="option" aria-selected="${c[0] === sel}" data-i="${i}"><img class="cc-flag" src="${FLAGS[c[0]]}" alt=""><span>${c[1]}</span><span class="code">${c[0].toUpperCase()}</span>${ic('check')}</button>`).join('') : '<div class="cc-none">No countries found</div>';
    idx = Math.max(0, shown.findIndex(c => c[0] === sel)); paint(true);
  }
  function paint(scroll){
    const its = $$('.cc-it', list); its.forEach((b, i) => b.classList.toggle('act', i === idx));
    const a = its[idx]; if (scroll && a){ const lr = list.getBoundingClientRect(), ar = a.getBoundingClientRect(); if (ar.top < lr.top || ar.bottom > lr.bottom) list.scrollTop += ar.top - lr.top - lr.height / 2 + ar.height / 2; }
  }
  function open(o){
    pop.classList.toggle('show', o); trig.setAttribute('aria-expanded', o);
    if (o){ q.value = ''; render(); setTimeout(() => q.focus(), 60); Sound.play('open'); } else Sound.play('close');
  }
  function choose(i){ const c = shown[i]; if (!c) return; sel = c[0]; paintTrig(); open(false); trig.focus(); Sound.play('select'); }
  trig.addEventListener('click', () => open(!pop.classList.contains('show')));
  trig.addEventListener('keydown', e => { if (e.key === 'ArrowDown' && !pop.classList.contains('show')){ e.preventDefault(); open(true); } });
  q.addEventListener('input', () => { render(); Sound.play('stream'); });
  q.addEventListener('keydown', e => {
    const n = shown.length;
    if ((e.key === 'ArrowDown' || e.key === 'ArrowUp') && n){ e.preventDefault(); idx = (idx + (e.key === 'ArrowDown' ? 1 : -1) + n) % n; paint(true); Sound.play('tick'); }
    else if (e.key === 'Enter'){ e.preventDefault(); choose(idx); }
    else if (e.key === 'Escape'){ open(false); trig.focus(); }
  });
  list.addEventListener('click', e => { const b = e.target.closest('.cc-it'); if (b) choose(+b.dataset.i); });
  list.addEventListener('mousemove', e => { const b = e.target.closest('.cc-it'); if (b && +b.dataset.i !== idx){ idx = +b.dataset.i; paint(false); } });
  document.addEventListener('pointerdown', e => { if (pop.classList.contains('show') && !$('#cc').contains(e.target)) open(false); });
  paintTrig();
}
